const { PrismaClient } = require('@prisma/client');
const fs = require('fs');

const prisma = new PrismaClient();

async function main() {
  // Clean up any existing categories to ensure a fresh tree
  await prisma.category.deleteMany({});

  // Create root
  const root = await prisma.category.create({
    data: { name: 'Electronics' },
  });

  // Create child
  const child = await prisma.category.create({
    data: { name: 'Phones', parentId: root.id },
  });

  // Create grandchild
  const grandchild = await prisma.category.create({
    data: { name: 'Smartphones', parentId: child.id },
  });

  // Query root with nested children
  const result = await prisma.category.findFirst({
    where: { name: 'Electronics' },
    include: { children: { include: { children: true } } },
  });

  fs.writeFileSync('/home/user/myproject/tree_result.json', JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result, null, 2));
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
EOF

